import{_ as a,o as i,c as n,a3 as t}from"./chunks/framework.iKZ1V-y0.js";const h=JSON.parse('{"title":"1.6 Full-Storage Oscillation Plan","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"1\\\\.6满仓震荡方案","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-JEibHxjUhjwaznRy5jp6oc.md","filePath":"logistics/src/page-JEibHxjUhjwaznRy5jp6oc.md","lastUpdated":null}'),s={name:"logistics/src/page-JEibHxjUhjwaznRy5jp6oc.md"};function o(r,e,l,p,c,d){return i(),n("div",null,[...e[0]||(e[0]=[t('<div class="logistics-content"><span class="logistics-source-anchor" id="_1-6满仓震荡方案" aria-hidden="true"></span><h1 id="_1-6-full-storage-oscillation-plan" tabindex="-1">1.6 Full-Storage Oscillation Plan <a class="header-anchor" href="#_1-6-full-storage-oscillation-plan" aria-label="Permalink to &quot;1.6 Full-Storage Oscillation Plan&quot;">​</a></h1><blockquote><p>Source page ID: <code>JEibHxjUhjwaznRy5jp6oc</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span class="mark-red"><strong>#言: Where&#39;s my Xiranite?</strong></span></p><p>To do:</p><p>Properly adapt high-efficiency disposal: clean-water node? Medicinal-solution handling? Number of water pumps? (Not adding these for now.)</p><p>Requirements:</p><p>Jingyu Valley: 12 Xiranite units with two Depot Loader inputs each. The self-starting plan with 12 such units and 9 Control Ports is ready. Cursed-engineering point: the facility count has exploded.</p><p>Other sections:</p><p>Yinglung Pass: remove Xiranite oversupply, place the automatically connected conduits outside, and add things (Separator Cores).</p><p>The main base needs compression (Refining Units, Sewage-treatment trash can, Xircon line, Ferrium refining/shredding and Separator Cores, half-rate batteries/, Xiranite oscillation/, Xiranite fluid-gas transmutation/, Xiranite bus/, Heavy Xiranite/). [Main problems: the battery line is not ready; high-efficiency disposal is not ready; external water pumps and Convergers; conduits longer than 50 tiles; self-starting Xiranite oscillation.]</p><p>Current layout:</p><p><span id="source-block-pZevVPXGlCFmWxYpA22zV7"></span></p><span class="logistics-source-anchor" id="景玉谷" aria-hidden="true"></span><h2 id="jingyu-valley" tabindex="-1">Jingyu Valley <a class="header-anchor" href="#jingyu-valley" aria-label="Permalink to &quot;Jingyu Valley&quot;">​</a></h2><p>12 Forges of the Sky, nine with two Depot Loader inputs each + the original Marker Stone setup + a suitable amount of Separator Core production/shredding.</p><p><span class="mark-grey">言: 12 Xiranite/3 Cuprium refining + 3 shredding/1-2 Separator Cores/a planting group (1 Yazhen, 1 Jincao) + 2 shredding seems fairly definite? Remaining space can fit SC Wuling Batteries or Ferrium refining + shredding.</span></p><p>Marker Stone: completely empty.</p><p>Main base: add SC Wuling Batteries.</p><p>Yinglung Pass: unchanged.</p><p><span id="source-block-FBtPNvsLFil3Wtwnz99gI5"></span></p><span class="logistics-source-anchor" id="散装模块" aria-hidden="true"></span><h2 id="standalone-modules" tabindex="-1">Standalone Modules <a class="header-anchor" href="#standalone-modules" aria-label="Permalink to &quot;Standalone Modules&quot;">​</a></h2><p><span id="source-block-h3O6ZElo5DYvpwQqWExr9k"></span></p><span class="logistics-source-anchor" id="蓝铁处理" aria-hidden="true"></span><h3 id="ferrium-processing" tabindex="-1">Ferrium Processing <a class="header-anchor" href="#ferrium-processing" aria-label="Permalink to &quot;Ferrium Processing&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-abd42c7b4bee2263.q90-fcf8ba08a760fb80.webp" alt="1.6 Full-Storage Oscillation Plan"></p><p><span id="source-block-V6Z6WWObS8Sp9VROKaVcgK"></span></p><span class="logistics-source-anchor" id="息壤" aria-hidden="true"></span><h3 id="xiranite" tabindex="-1">Xiranite <a class="header-anchor" href="#xiranite" aria-label="Permalink to &quot;Xiranite&quot;">​</a></h3><p><span class="mark-red">Where is it? Hurry up and bring it out!!!</span></p><p><span id="source-block-PSVH9EWPl3In6oiZbgmPV9"></span></p><span class="logistics-source-anchor" id="息壤液满仓震荡模块" aria-hidden="true"></span><h3 id="liquid-xiranite-full-storage-oscillation-module" tabindex="-1">Liquid Xiranite Full-Storage Oscillation Module <a class="header-anchor" href="#liquid-xiranite-full-storage-oscillation-module" aria-label="Permalink to &quot;Liquid Xiranite Full-Storage Oscillation Module&quot;">​</a></h3><p><span id="source-block-qFVfEvK9jO1NhKefnV1XSG"></span></p><span class="logistics-source-anchor" id="控息壤" aria-hidden="true"></span><h4 id="controlling-xiranite" tabindex="-1">Controlling Xiranite <a class="header-anchor" href="#controlling-xiranite" aria-label="Permalink to &quot;Controlling Xiranite&quot;">​</a></h4><p><span id="source-block-GiL6uZNnTppYmPRchrcBmr"></span></p><span class="logistics-source-anchor" id="控水" aria-hidden="true"></span><h4 id="controlling-water" tabindex="-1">Controlling Water <a class="header-anchor" href="#controlling-water" aria-label="Permalink to &quot;Controlling Water&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7c56052227e27422.q90-4b211e99002b0a11.webp" alt="1.6 Full-Storage Oscillation Plan"></p><p>Filler: put 250 Jincao in every box except the unpowered one at the far left. Fill the unpowered tank with 4 miscellaneous items, and use enough Jincao Seeds to fill the length of the belt.</p><p>This should save a great many facilities, at the cost of only 4 pipe components. I have not compressed it yet, though ((</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-66cb72c1992c90de.q90-436844d24ec0f6d8.webp" alt="1.6 Full-Storage Oscillation Plan"></p><p>Initial compression is complete. Preparing the unpowered tank takes quite a while; I do not know whether to optimize that.</p><p>Arknights: Endfield blueprint [Wuling Unpowered Tank], share code EF01E75U77u25o5683uIa. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Oscillating Liquid Xiranite], share code EF01081388U91i1o5E179. Copy it and use it in the game.</p></div>',1)])])}const g=a(s,[["render",o]]);export{h as __pageData,g as default};
